<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {get,put} from '@/net';import {ElMessage} from 'element-plus'
const route=useRoute();const router=useRouter();const id=Number(route.params.id);const form=reactive({title:'',content:'',resourceUrl:''});const saving=ref(false);const expectedUpdateTime=ref<number|null>(null)
onMounted(()=>get('/api/post/'+id,{},r=>{const p=r.data?.data;if(p){const draft=sessionStorage.getItem(`ai-draft:${id}`);const draftVersion=sessionStorage.getItem(`ai-draft-version:${id}`);form.title=p.title;form.content=draft||p.content;form.resourceUrl=p.resourceUrl;expectedUpdateTime.value=draft&&draftVersion?Number(draftVersion):null;sessionStorage.removeItem(`ai-draft:${id}`);sessionStorage.removeItem(`ai-draft-version:${id}`)}}))
function save(){if(!form.title.trim()||!form.content.trim()||!/^https?:\/\/\S+$/.test(form.resourceUrl.trim())){ElMessage.warning('请完整填写有效内容');return}saving.value=true;const payload:any={...form,title:form.title.trim(),resourceUrl:form.resourceUrl.trim()};if(expectedUpdateTime.value!==null)payload.expectedUpdateTime=expectedUpdateTime.value;put('/api/post/'+id,payload,()=>{saving.value=false;ElMessage.success('保存成功');router.push('/post/'+id)},res=>{saving.value=false;ElMessage.error(res.data?.message||'保存失败，请稍后重试')},()=>{saving.value=false;ElMessage.error('网络错误，请检查后端服务')})}
</script>
<template><div class="page"><header><strong @click="router.push('/index')">资源站</strong><button @click="router.back()">返回</button></header><main><section><h1>编辑帖子</h1><label>标题<input v-model="form.title" maxlength="100"></label><label>资源链接<input v-model="form.resourceUrl" maxlength="2048"></label><label>正文<textarea v-model="form.content" maxlength="10000" rows="12"></textarea></label><button class="save" :disabled="saving" @click="save">{{saving?'保存中...':'保存修改'}}</button></section></main></div></template>
<style scoped>.page{min-height:100vh;background:#0b151b}header{height:60px;background:rgba(10,25,30,.86);border-bottom:1px solid rgba(103,161,157,.24);display:flex;align-items:center;justify-content:space-between;padding:0 20px}header strong{color:#83f5e6;cursor:pointer}button{padding:8px 16px;border:1px solid rgba(126,224,210,.35);background:rgba(10,25,30,.86);color:#83f5e6;border-radius:6px}main{max-width:860px;margin:auto;padding:24px 20px}section{background:rgba(10,25,30,.86);padding:30px;border-radius:8px}h1{margin-top:0}label{display:block;font-weight:600;margin:18px 0}input,textarea{display:block;width:100%;box-sizing:border-box;margin-top:8px;padding:11px;border:1px solid rgba(103,161,157,.24);border-radius:6px;font:inherit}.save{background:#83f5e6;color:#fff;border:0}</style>

<style scoped src="../styles/page-shell.css"></style>
